def _ordered_flow_roots(
    groups: Iterable[Iterable[_FlowValue]], budget: _AnalysisBudget,
) -> tuple[_FlowValue, ...]:
    # Two containers and the outer iterator; keys include the complete ref tuple.
    budget.consume(3)
    result: list[_FlowValue] = []
    seen: set[tuple[int, tuple[int, ...]]] = set()
    for group in groups:
        budget.consume(2)  # Group visit and its iterator.
        for value in group:
            budget.consume(6 + len(value.authority_refs))
            key = (id(value), value.authority_refs)
            if key not in seen:
                budget.consume(2 + len(value.authority_refs))
                seen.add(key)
                result.append(value)
    budget.consume(1 + len(result))
    return tuple(result)

def _join_member_obligations(
    left: tuple[tuple[str, tuple[_FlowValue, ...]], ...],
    right: tuple[tuple[str, tuple[_FlowValue, ...]], ...],
    budget: _AnalysisBudget,
) -> tuple[tuple[str, tuple[_FlowValue, ...]], ...]:
    budget.consume()
    if left is right:
        return left
    budget.consume(6)  # Dict/list, operand tuple with two refs, and iterator.
    grouped: dict[str, list[tuple[_FlowValue, ...]]] = {}
    result: list[tuple[str, tuple[_FlowValue, ...]]] = []
    for supplied in (left, right):
        budget.consume(2)
        for name, roots in supplied:
            budget.consume(3)  # Entry visit, lookup and bucket-reference read.
            bucket = grouped.get(name)
            if bucket is None:
                budget.consume(4)  # List allocation, dict attempt and two references.
                bucket = []
                grouped[name] = bucket
            budget.consume()
            bucket.append(roots)
    budget.consume(2)  # Items view and iterator.
    for name, groups in grouped.items():
        budget.consume()
        roots = _ordered_flow_roots(groups, budget)
        if roots:
            budget.consume(4)  # Pair allocation, its refs and result append.
            result.append((name, roots))
    budget.consume(1 + len(result))
    return tuple(result)

def _new_retained_value(
    budget: _AnalysisBudget, kind: str, value: object = None, **fields: object,
) -> _FlowValue:
    # FlowValue allocation + eighteen field refs; explicit kwargs copy.
    budget.consume(20 + 2 * len(fields))
    return _FlowValue(kind, value, **fields)


def _replace_retained_metadata(
    value: _FlowValue | _AuthorityRecord, budget: _AnalysisBudget, **changes: object,
) -> _FlowValue | _AuthorityRecord:
    # New record allocation/fields and the explicit override dictionary.
    budget.consume(2 + (18 if isinstance(value, _FlowValue) else 6) + 2 * len(changes))
    return replace(value, **changes)


def _append_retained_edge(
    edges: list[tuple[str, _FlowValue]], role: str, value: _FlowValue,
    budget: _AnalysisBudget,
) -> None:
    budget.consume(4)  # Pair allocation, two pair refs, destination-list ref.
    edges.append((role, value))


def _push_ordered_retained_edges(
    pending: list[tuple[str, _FlowValue]], edges: Sequence[tuple[str, _FlowValue]],
    budget: _AnalysisBudget,
) -> None:
    budget.consume(1)  # Reverse iterator; no sorting or private-ID ordering.
    for edge in reversed(edges):
        budget.consume(2)  # Visit and pending reference copy.
        pending.append(edge)

def _result_boundary_evidence(
    self, value: _FlowValue, values: Mapping[str, _FlowValue], *, immediate: bool,
) -> tuple[tuple[_FlowValue, ...], tuple[_FlowValue, ...]]:
    """Discover deferred values/issues without consuming their retained graph."""
    self.budget.consume(6)  # Pending, two seen sets, two result lists, initial edge list.
    pending: list[tuple[str, _FlowValue]] = []
    seen_values: set[tuple[str, int]] = set()
    seen_authority: set[tuple[str, int]] = set()
    deferred: list[_FlowValue] = []
    issues: list[_FlowValue] = []
    initial: list[tuple[str, _FlowValue]] = []
    _append_retained_edge(initial, "alternative", value, self.budget)
    _push_ordered_retained_edges(pending, initial, self.budget)
    store = self._authority(values)
    while pending:
        self.budget.consume(2)  # Pop and edge visit.
        role, current = pending.pop()
        if immediate and role == "element":
            continue
        self.budget.consume(4)  # Key allocation/refs and seen lookup.
        key = (role, id(current))
        if key in seen_values:
            continue
        self.budget.consume(2)  # Seen insert and child-edge list allocation.
        seen_values.add(key)
        edges: list[tuple[str, _FlowValue]] = []
        if current.authority_refs:
            self.budget.consume()  # Ref iterator.
            for identity in current.authority_refs:
                self.budget.consume(5)  # Visit, key allocation/refs, lookup.
                authority_key = (role, identity)
                if authority_key in seen_authority:
                    continue
                self.budget.consume(2)  # Seen insert and current-store lookup.
                seen_authority.add(authority_key)
                record = store.objects.get(identity)
                if record is None:
                    issue = _new_retained_value(
                        self.budget, "helper_deferred_refusal",
                        reason="helper namespace authority state is unresolved",
                    )
                    _append_retained_edge(edges, role, issue, self.budget)
                    projected = _replace_retained_metadata(
                        current, self.budget, authority_refs=(),
                    )
                    _append_retained_edge(edges, role, projected, self.budget)
                else:
                    _append_retained_edge(edges, role, record.value, self.budget)
                    retained_role = "element" if record.value.mutable_collection else role
                    self.budget.consume()
                    for retained in record.retained:
                        self.budget.consume()
                        _append_retained_edge(edges, retained_role, retained, self.budget)
            # Explicit result alternatives remain independent of a partial ref union.
            if current.callable_definition is None:
                self.budget.consume()
                for retained in current.helper_obligations:
                    self.budget.consume()
                    if retained.kind == "deferred_result_carrier":
                        _append_retained_edge(edges, role, retained, self.budget)
            _push_ordered_retained_edges(pending, edges, self.budget)
            continue
        if current.kind == "deferred_result_carrier" and isinstance(
            current.value, _DeferredResultCarrier,
        ):
            self.budget.consume()
            for retained in current.value.roots:
                self.budget.consume()
                child_role = "element" if role == "element" else current.value.role
                _append_retained_edge(edges, child_role, retained, self.budget)
        elif current.kind in {"generator", "deferred_local_generator"}:
            self.budget.consume()
            deferred.append(current)
        elif current.kind == "helper_deferred_refusal" or (
            current.callable_definition is None and current.helper_refusal is not None
        ):
            self.budget.consume()
            issues.append(current)
        elif current.kind == "deferred_generator_merged":
            self.budget.consume()
            for item in current.value:
                self.budget.consume()
                if isinstance(item, _DeferredGeneratorState):
                    item = _new_retained_value(self.budget, "generator", item)
                if isinstance(item, _FlowValue):
                    _append_retained_edge(edges, role, item, self.budget)
        else:
            if current.kind in {"maybe_unbound", "deferred_generator_container_merged"}:
                self.budget.consume()
                for item in current.value:
                    self.budget.consume()
                    if isinstance(item, _FlowValue):
                        _append_retained_edge(edges, role, item, self.budget)
            elif current.kind in {"sequence", "slice"} and not immediate:
                self.budget.consume()
                for item in current.value:
                    self.budget.consume()
                    if isinstance(item, _FlowValue):
                        _append_retained_edge(edges, "element", item, self.budget)
            elif current.kind in {"mapping", "mapping_keys"} and not immediate:
                self.budget.consume()
                for pair in current.value:
                    self.budget.consume(2)  # Pair visit and pair iterator.
                    for item in pair:
                        self.budget.consume()
                        if isinstance(item, _FlowValue):
                            _append_retained_edge(edges, "element", item, self.budget)
            elif current.kind == "starred_argument" and isinstance(current.value, _FlowValue):
                _append_retained_edge(edges, role, current.value, self.budget)
            if current.callable_definition is None and current.kind in {
                "unknown", "maybe_unbound", "deferred_generator_container_merged",
            }:
                self.budget.consume()
                for retained in current.helper_obligations:
                    self.budget.consume()
                    _append_retained_edge(edges, role, retained, self.budget)
        _push_ordered_retained_edges(pending, edges, self.budget)
    self.budget.consume(7)  # Two singleton group tuples, result pair and its refs.
    return (
        _ordered_flow_roots((deferred,), self.budget),
        _ordered_flow_roots((issues,), self.budget),
    )

def _deferred_result_values(
    self, value: _FlowValue, values: Mapping[str, _FlowValue], *, immediate: bool,
    all_deferred: bool = False,
) -> tuple[_FlowValue, ...]:
    # Kept as the existing discovery API; every deferred kind is retained.
    return self._result_boundary_evidence(value, values, immediate=immediate)[0]

def _has_result_obligations(
    self, value: _FlowValue, values: Mapping[str, _FlowValue],
) -> bool:
    deferred, issues = self._result_boundary_evidence(value, values, immediate=False)
    return bool(deferred or issues)

def _record_reached_result_issues(
    self, value: _FlowValue, values: Mapping[str, _FlowValue], site: ast.AST,
) -> bool:
    """Export result-associated issues only when this result is consumed."""
    _deferred, issues = self._result_boundary_evidence(value, values, immediate=True)
    self.budget.consume()
    for issue in issues:
        self.budget.consume(5)  # Visit, blocker pair/refs and append.
        reason = issue.helper_refusal or issue.reason or "helper namespace result is unresolved"
        self.flow.standalone_blockers.append((site, reason))
    return bool(issues)

def _retained_result_carrier(
    result: _FlowValue, role: str, roots: Iterable[_FlowValue], budget: _AnalysisBudget,
) -> _FlowValue:
    budget.consume(2)  # Singleton group tuple and its reference.
    supplied = _ordered_flow_roots((roots,), budget)
    if not supplied:
        return result
    budget.consume(3)  # Carrier payload allocation and two fields.
    carrier = _new_retained_value(
        budget, "deferred_result_carrier", _DeferredResultCarrier(role, supplied),
    )
    budget.consume(2 + len(result.helper_obligations))
    return _replace_retained_metadata(
        result, budget, authority_refs=(),
        helper_obligations=(*result.helper_obligations, carrier),
    )

def _carrier_result(
    self, result: _FlowValue, role: Literal["alternative", "element"],
    roots: Iterable[_FlowValue],
) -> _FlowValue:
    return _retained_result_carrier(result, role, roots, self.budget)

def _element_result_values(
    self, value: _FlowValue, values: Mapping[str, _FlowValue],
) -> tuple[_FlowValue, ...]:
    """Extract one containment layer, never execute or flatten its elements."""
    self.budget.consume(6)
    pending: list[tuple[str, _FlowValue]] = []
    initial: list[tuple[str, _FlowValue]] = []
    seen_values: set[tuple[str, int]] = set()
    seen_authority: set[tuple[str, int]] = set()
    result: list[_FlowValue] = []
    _append_retained_edge(initial, "alternative", value, self.budget)
    _push_ordered_retained_edges(pending, initial, self.budget)
    store = self._authority(values)
    while pending:
        self.budget.consume(2)
        role, current = pending.pop()
        if role == "element":
            self.budget.consume()
            result.append(current)
            continue
        self.budget.consume(4)
        key = (role, id(current))
        if key in seen_values:
            continue
        self.budget.consume(2)
        seen_values.add(key)
        edges: list[tuple[str, _FlowValue]] = []
        if current.authority_refs:
            self.budget.consume()
            for identity in current.authority_refs:
                self.budget.consume(5)
                authority_key = (role, identity)
                if authority_key in seen_authority:
                    continue
                self.budget.consume(2)
                seen_authority.add(authority_key)
                record = store.objects.get(identity)
                if record is None:
                    issue = _new_retained_value(
                        self.budget, "helper_deferred_refusal",
                        reason="helper namespace authority state is unresolved",
                    )
                    _append_retained_edge(edges, "element", issue, self.budget)
                    projected = _replace_retained_metadata(
                        current, self.budget, authority_refs=(),
                    )
                    _append_retained_edge(edges, "alternative", projected, self.budget)
                else:
                    _append_retained_edge(edges, "alternative", record.value, self.budget)
                    self.budget.consume()
                    for retained in record.retained:
                        self.budget.consume()
                        if retained.kind == "deferred_result_carrier":
                            _append_retained_edge(edges, "alternative", retained, self.budget)
                        elif record.value.mutable_collection:
                            _append_retained_edge(edges, "element", retained, self.budget)
            if current.callable_definition is None:
                self.budget.consume()
                for retained in current.helper_obligations:
                    self.budget.consume()
                    if retained.kind == "deferred_result_carrier":
                        _append_retained_edge(edges, "alternative", retained, self.budget)
        elif current.kind == "deferred_result_carrier" and isinstance(
            current.value, _DeferredResultCarrier,
        ):
            self.budget.consume()
            for retained in current.value.roots:
                self.budget.consume()
                _append_retained_edge(edges, current.value.role, retained, self.budget)
        elif current.kind in {"sequence", "slice"}:
            self.budget.consume()
            for item in current.value:
                self.budget.consume()
                if isinstance(item, _FlowValue):
                    _append_retained_edge(edges, "element", item, self.budget)
        elif current.kind in {"mapping", "mapping_keys"}:
            self.budget.consume()
            for pair in current.value:
                self.budget.consume(2)
                for item in pair:
                    self.budget.consume()
                    if isinstance(item, _FlowValue):
                        _append_retained_edge(edges, "element", item, self.budget)
        elif current.kind in {"maybe_unbound", "deferred_generator_container_merged"}:
            self.budget.consume()
            for item in current.value:
                self.budget.consume()
                if isinstance(item, _FlowValue):
                    _append_retained_edge(edges, "alternative", item, self.budget)
        elif current.kind == "helper_deferred_refusal" or (
            current.callable_definition is None and current.helper_refusal is not None
        ):
            _append_retained_edge(edges, "element", current, self.budget)
        if not current.authority_refs and current.callable_definition is None and current.kind in {
            "unknown", "maybe_unbound", "deferred_generator_container_merged",
        }:
            self.budget.consume()
            for retained in current.helper_obligations:
                self.budget.consume()
                _append_retained_edge(edges, "alternative", retained, self.budget)
        _push_ordered_retained_edges(pending, edges, self.budget)
    self.budget.consume(2)
    return _ordered_flow_roots((result,), self.budget)

