def _class_member_owner_ids(
    self, owner: _FlowValue, values: Mapping[str, _FlowValue], *,
    instance_read: bool = False, member_lookup: bool = False,
) -> tuple[tuple[int, ...], bool, tuple[_FlowValue, ...]]:
    """Preserve every immediate owner alternative, independently of live ref unions."""
    self.budget.consume(6)
    pending: list[tuple[str, _FlowValue]] = []
    initial: list[tuple[str, _FlowValue]] = []
    seen_values: set[tuple[str, int]] = set()
    seen_authority: set[tuple[str, int]] = set()
    identities: list[int] = []
    issues: list[_FlowValue] = []
    unresolved = False
    _append_retained_edge(initial, "receiver", owner, self.budget)
    _push_ordered_retained_edges(pending, initial, self.budget)
    store = self._authority(values)
    while pending:
        self.budget.consume(6)
        role, current = pending.pop()
        key = (role, id(current))
        if key in seen_values:
            continue
        self.budget.consume(2)
        seen_values.add(key)
        edges: list[tuple[str, _FlowValue]] = []
        if current.callable_definition is not None:
            continue
        if current.kind == "implicit_class_instance" and not instance_read:
            continue
        if current.kind == "class_member_base":
            if member_lookup and isinstance(current.value, _FlowValue):
                _append_retained_edge(edges, "base", current.value, self.budget)
            _push_ordered_retained_edges(pending, edges, self.budget)
            continue
        if current.helper_refusal is not None or current.kind == "helper_deferred_refusal":
            self.budget.consume()
            issues.append(current)
        explicit_class = bool(current.kind == "implicit_class" or (
            current.helper_provenance is not None and current.helper_provenance.kind == "class"
        ))
        if current.authority_refs:
            self.budget.consume()
            for identity in current.authority_refs:
                self.budget.consume(5)
                authority_key = (role, identity)
                if authority_key in seen_authority:
                    continue
                self.budget.consume(2)
                seen_authority.add(authority_key)
                record = store.objects.get(identity)
                if record is None:
                    unresolved |= explicit_class
                    issue = _new_retained_value(
                        self.budget, "helper_deferred_refusal",
                        reason="helper namespace authority state is unresolved",
                    )
                    self.budget.consume()
                    issues.append(issue)
                elif record.class_member_owner:
                    self.budget.consume()
                    identities.append(identity)
                    if member_lookup:
                        self.budget.consume()
                        for retained in record.value.helper_obligations:
                            self.budget.consume()
                            if retained.kind == "class_member_base":
                                _append_retained_edge(edges, role, retained, self.budget)
                else:
                    _append_retained_edge(edges, role, record.value, self.budget)
                    if not record.value.mutable_collection:
                        self.budget.consume()
                        for retained in record.retained:
                            self.budget.consume()
                            _append_retained_edge(edges, role, retained, self.budget)
            # These are original operand/result edges, not old record contents.
            self.budget.consume()
            for retained in current.helper_obligations:
                self.budget.consume()
                if retained.kind == "deferred_result_carrier":
                    _append_retained_edge(edges, role, retained, self.budget)
            _push_ordered_retained_edges(pending, edges, self.budget)
            continue
        if explicit_class:
            unresolved = True
            if role == "base":
                issue = _new_retained_value(
                    self.budget, "helper_deferred_refusal",
                    reason="helper namespace inherited member authority is unresolved",
                )
                self.budget.consume()
                issues.append(issue)
        elif role == "base" and not current.helper_obligations and current.kind not in {
            "deferred_result_carrier", "maybe_unbound", "implicit_protocol_merged",
        }:
            issue = _new_retained_value(
                self.budget, "helper_deferred_refusal",
                reason="helper namespace inherited member authority is unresolved",
            )
            self.budget.consume()
            issues.append(issue)
        if current.kind == "deferred_result_carrier" and isinstance(
            current.value, _DeferredResultCarrier,
        ):
            if current.value.role == "alternative":
                self.budget.consume()
                for retained in current.value.roots:
                    self.budget.consume()
                    _append_retained_edge(edges, role, retained, self.budget)
        else:
            if current.kind in {
                "maybe_unbound", "implicit_protocol_merged", "deferred_generator_container_merged",
            }:
                self.budget.consume()
                for retained in current.value:
                    self.budget.consume()
                    if isinstance(retained, _FlowValue):
                        _append_retained_edge(edges, role, retained, self.budget)
            self.budget.consume()
            for retained in current.helper_obligations:
                self.budget.consume()
                if retained.kind in {"deferred_result_carrier", "class_member_base"} or (
                    current.kind in {"unknown", "implicit_class", "implicit_class_instance"}
                ):
                    _append_retained_edge(edges, role, retained, self.budget)
        _push_ordered_retained_edges(pending, edges, self.budget)
    self.budget.consume(9 + 3 * len(identities))
    return tuple(dict.fromkeys(identities)), unresolved, _ordered_flow_roots((issues,), self.budget)

