def _current_collection_read_value(
    self, owner: _FlowValue, values: Mapping[str, _FlowValue],
) -> _FlowValue:
    """Refresh a captured native collection, never re-evaluate its expression."""
    self.budget.consume()
    if not owner.authority_refs:
        return owner
    store = self._authority(values)
    self.budget.consume(2)
    records: list[_AuthorityRecord | None] = []
    managed = bool(owner.kind in {"sequence", "mapping"} or (
        owner.mutable_collection and owner.mutable_collection_identity is not None
    ))
    for identity in owner.authority_refs:
        self.budget.consume(3)
        record = store.objects.get(identity)
        records.append(record)
        managed |= bool(record is not None and not record.class_member_owner and (
            record.value.mutable_collection or record.value.kind in {"sequence", "mapping"}
        ))
    if not managed:
        return owner
    exact = True
    unchanged = True
    self.budget.consume()
    for record in records:
        self.budget.consume()
        if record is None or record.class_member_owner or record.retained or (
            record.value.kind not in {"sequence", "mapping"}
        ):
            exact = False
            unchanged = False
            continue
        # Identity comparisons prove unchanged metadata without nested equality.
        self.budget.consume()
        for field_name in (
            "kind", "value", "sensitive", "reason", "mutable_collection",
            "mutable_collection_identity", "container_kind", "helper_provenance",
            "callable_defaults", "namespace_effects", "helper_refusal", "helper_receiver",
            "callable_definition", "callable_scope", "callable_free_values",
            "helper_obligations", "native_unstarted_coroutine",
        ):
            self.budget.consume(4)
            if getattr(record.value, field_name) is not getattr(owner, field_name):
                unchanged = False
                break
    if unchanged:
        return owner
    if exact:
        self.budget.consume(2 + 2 * len(records))
        current = _merge_flow_values(
            "current collection read", tuple(record.value for record in records),
            budget=self.budget,
        )
        if current.kind in {"sequence", "mapping"}:
            # Independent explicit result alternatives remain negative evidence.
            self.budget.consume(2 + len(owner.helper_obligations))
            alternatives = tuple(item for item in owner.helper_obligations
                                 if item.kind == "deferred_result_carrier")
            self.budget.consume(3 + len(current.helper_obligations) + len(alternatives))
            obligations = _ordered_flow_roots(
                (current.helper_obligations, alternatives), self.budget,
            )
            return _replace_retained_metadata(
                current, self.budget, authority_refs=owner.authority_refs,
                helper_obligations=obligations,
            )
    # Missing records never demote a recognized managed collection to unmanaged.
    elements = self._element_result_values(owner, values)
    opaque = self._carrier_result(
        _replace_retained_metadata(
            owner, self.budget, kind="unknown", value=None, authority_refs=(),
            helper_obligations=(), reason="current collection contents are unresolved",
        ),
        "element", elements,
    )
    return _replace_retained_metadata(
        opaque, self.budget, authority_refs=owner.authority_refs,
    )

def _invalidate_collection_result_shape(
    self, owner: _FlowValue, values: Mapping[str, _FlowValue],
) -> None:
    store = self._authority(values)
    self.budget.consume()
    for identity in owner.authority_refs:
        self.budget.consume(2)
        record = store.objects.get(identity)
        if record is None:
            continue
        self.budget.consume(2)
        current = _replace_retained_metadata(
            record.value, self.budget, authority_refs=(identity,),
        )
        children = self._element_result_values(current, values)
        carrier = self._carrier_result(
            _new_retained_value(
                self.budget, "unknown", reason="collection result shape is unresolved",
            ), "element", children,
        )
        self.budget.consume(3)
        roots = _ordered_flow_roots(
            (record.retained, carrier.helper_obligations), self.budget,
